text:
{
  "title_novice": "Контроль коррозии колонны",
  "summary": [
    {"text": "Целостность стальной колонны проверяют на протяжении всей жизни скважины.", "claims": ["c1"]},
    {"text": "Для этого применяют каверномеры, толщиномеры и неразрушающие методы: ультразвуковые, электромагнитные и магнитные.", "claims": ["c1", "c2"]},
    {"text": "Неразрушающие методы проверяют колонну, не портя её.", "claims": ["c3"]}
  ],
  "claims": [
    {"key": "c1", "text": "Целостность стальной и цементированной колонны контролируют на протяжении всей жизни скважины с помощью каверномеров и толщиномеров.", "kind": "observation", "unit_id": "u-107-37e70c", "page": 107, "quote": "Throughout the life of the wells, integrity controles of the steel and cemented column (casing and tubing) are performed using calipers and thickness gauges.", "numbers": [], "question": null},
    {"key": "c2", "text": "Для контроля колонны применяют передовые технические методы с ультразвуковыми, электромагнитными и магнитными преобразователями.", "kind": "observation", "unit_id": "u-107-37e70c", "page": 107, "quote": "These advanced technical methods use non destructive technologies as ultrasonic, electromagnetic and magnetic transducers.", "numbers": [], "question": null},
    {"key": "c3", "text": "Эти методы неразрушающие, то есть проверка не разрушает саму колонну.", "kind": "inference", "unit_id": "u-107-37e70c", "page": 107, "quote": "These advanced technical methods use non destructive technologies as ultrasonic, electromagnetic and magnetic transducers.", "numbers": [], "question": null},
    {"key": "c4", "text": "Проверяемая колонна состоит из стали и цемента и включает обсадные трубы и насосно-компрессорные трубы.", "kind": "assumption", "unit_id": "u-107-37e70c", "page": 107, "quote": "Throughout the life of the wells, integrity controles of the steel and cemented column (casing and tubing) are performed using calipers and thickness gauges.", "numbers": [], "question": null}
  ],
  "mechanism": [
    {"text": "Контроль целостности ведут на протяжении всей жизни скважины, а не только при её строительстве.", "claims": ["c1"], "hypothesis": false},
    {"text": "Проверяемая колонна включает обсадные и насосно-компрессорные трубы из стали и цемента.", "claims": ["c4"], "hypothesis": false},
    {"text": "Каверномер и толщиномер — два инструмента, которые книга называет для контроля колонны.", "claims": ["c1"], "hypothesis": false},
    {"text": "Ультразвуковой, электромагнитный и магнитный датчики относятся к неразрушающим технологиям.", "claims": ["c2"], "hypothesis": false},
    {"text": "Ультразвуковой датчик посылает импульс и по времени возврата эха оценивает толщину стенки.", "claims": [], "hypothesis": true},
    {"text": "Электромагнитный и магнитный отклик зависит от металла колонны; изменение металла меняет отклик.", "claims": [], "hypothesis": true}
  ],
  "practice": [
    {"text": "Специалист выбирает метод по задаче: диаметр, толщина стенки или состояние металла.", "claims": [], "hypothesis": true},
    {"text": "Проверку повторяют во времени и сравнивают новые результаты с прошлыми замерами.", "claims": [], "hypothesis": true}
  ],
  "nuances": [
    {"text": "Термин «неразрушающий» описывает саму проверку, а не состояние колонны.", "claims": ["c3"], "hypothesis": false},
    {"text": "Пороги толщины и диаметра, при которых колонну признают негодной, в главе не даны.", "claims": [], "hypothesis": true},
    {"text": "Вокруг колонны есть цемент, поэтому сигнал может отражать и цемент, а не только металл.", "claims": [], "hypothesis": true}
  ],
  "deeper": [
    {"title": "Почему ультразвук и магнетизм дают разные сведения", "text": "Ультразвук чувствителен к границам слоёв металла и цемента; магнитные методы — к самому металлу. В главе это не описано.", "claims": [], "hypothesis": true}
  ],
  "procedure": [],
  "numbers_conditions": [
    {"text": "Условие: контроль ведут на протяжении всей жизни скважины.", "claims": ["c1"]},
    {"text": "Объект проверки: стальная и цементированная колонна, включая обсадные и насосно-компрессорные трубы.", "claims": ["c4"]},
    {"text": "Числовых порогов и допусков в главе нет.", "claims": []}
  ],
  "terms_defined": [
    {"term": "насосно-компрессорная труба", "term_en": "tubing", "abbr": "НКТ", "definition": "Труба, по которой флюид поднимают к устью; спускается внутрь обсадной колонны. Определение общее, в главе не дано.", "claims": ["c4"]},
    {"term": "цементное кольцо", "term_en": "cement sheath", "abbr": "", "definition": "Слой цемента между колонной и стенкой скважины, который закрепляет колонну. Определение общее; книга говорит о цементированной колонне.", "claims": ["c4"]},
    {"term": "неразрушающий контроль", "term_en": "non-destructive testing (NDT)", "abbr": "НК", "definition": "Проверка объекта без его разрушения. Книга относит к ней ультразвуковой, электромагнитный и магнитный методы.", "claims": ["c2", "c3"]},
    {"term": "толщиномер", "term_en": "thickness gauge", "abbr": "", "definition": "Прибор, который измеряет толщину стенки колонны.", "claims": ["c1"]},
    {"term": "коррозия", "term_en": "corrosion", "abbr": "", "definition": "Постепенное разрушение металла при взаимодействии с окружающей средой. Определение общее, в главе не дано.", "claims": []}
  ],
  "terms_used": ["каротаж", "обсадная колонна", "эксплуатационная колонна", "каверномер", "целостность скважины"],
