  "misconception": {
    "pack_id": null,
    "wrong": "Колонну проверяют один раз при строительстве скважины; потом её состояние не меняется и контроль не нужен.",
    "right": "Целостность колонны контролируют на протяжении всей жизни скважины.",
    "claims": ["c1"]
  },
  "data_meaning": {
    "inputs": [
      {"text": "Диаметр колонны по показаниям каверномера и толщина стенки по толщиномеру.", "claims": ["c1"], "hypothesis": false},
      {"text": "Время возврата эха от стенок колонны для ультразвукового датчика.", "claims": [], "hypothesis": true},
      {"text": "Отклик металла колонны на электромагнитный и магнитный датчики вдоль глубины.", "claims": [], "hypothesis": true}
    ],
    "outputs": [
      {"text": "Толщина стенки и диаметр колонны по глубине.", "claims": [], "hypothesis": true}
    ],
    "breaks": [
      {"text": "Отклик зависит от металла, цемента и зазоров; разные факторы могут давать похожий сигнал.", "claims": [], "hypothesis": true}
    ]
  },
  "it_analogy": {
    "pack_id": "IT01",
    "analogy": "Показание толщиномера — как метрика здоровья сервиса: это отклик датчика, а не само состояние колонны.",
    "breaks_where": "Колонне нельзя посмотреть логи. Её состояние узнают по отклику приборов; эталоны и калибровку в главе не описаны."
  },
  "now_nuance": {
    "text": "Гипотеза (не из главы): сегодня для контроля колонны чаще применяют многорычажные каверномеры и электромагнитные дефектоскопы с многими датчиками; ультразвуковые приборы тоже сохраняются."
  },
  "threshold": {
    "is_threshold": false,
    "why": "Узел прикладной: он описывает, как проверяют колонну, и не даёт новой физической модели."
  },
  "inefficiency": {
    "inputs": [
      "Геометрия колонны: диаметр по каверномеру и толщина стенки по толщиномеру.",
      "Гипотеза: данные прошлых замеров того же ствола для сравнения."
    ],
    "manual_steps": [
      "Гипотеза: спуск прибора внутрь колонны и подъём с записью отклика."
    ],
    "judgment_points": [
      "Гипотеза: выбор метода под задачу — диаметр, толщина или состояние металла.",
      "Гипотеза: решение, насколько изменение отклика значимо и требует действий."
    ],
    "time": [
      "Контроль ведут на протяжении всей жизни скважины, то есть это повторяющаяся работа (из главы)."
    ],
    "typical_errors": [
      "Гипотеза: проверить колонну один раз и считать её состояние известным навсегда.",
      "Гипотеза: принять отклик цемента за признак дефекта металла."
    ]
